      ]
    };

    const searchInput = document.getElementById('searchInput');
    const autocomplete = document.getElementById('autocomplete');

    searchInput.addEventListener('input', (e) => {
      const query = e.target.value.trim().toLowerCase();

      if (query.length < 2) {
        autocomplete.classList.remove('active');
        return;
      }

      const filteredSpecialties = autocompleteData.specialties.filter(s =>
        s.name.toLowerCase().includes(query) || s.sub.toLowerCase().includes(query)
      );
      const filteredConditions = autocompleteData.conditions.filter(c =>
        c.name.toLowerCase().includes(query) || c.sub.toLowerCase().includes(query)
      );
      const filteredDoctors = autocompleteData.doctors.filter(d =>
