      const query = searchInput.value || document.getElementById('searchInput').placeholder;
      const location = document.getElementById('locationSelect').value;
      const insurance = document.getElementById('insuranceSelect').value;

      // Simulate search redirect
      let url = '/search?q=' + encodeURIComponent(query);
      if (location) url += '&location=' + encodeURIComponent(location);
      if (insurance) url += '&insurance=' + encodeURIComponent(insurance);

      alert('Searching for: ' + query + (location ? ' in ' + location : '') + (insurance ? ' with ' + insurance + ' insurance' : ''));
    });

    // Smooth scroll for anchor links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function(e) {
        const href = this.getAttribute('href');
        if (href !== '#') {
          e.preventDefault();
          const target = document.querySelector(href);
          if (target) {
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }
        }
      });
    });
  </script>
